    for _ in range(N):
        s = input[idx]
        c = int(input[idx+1])
        strings.append((s, c))
        idx += 2

    min_cost = float('inf')

    # Check single strings
    for s, c in strings:
        if is_palindrome(s):
            if c < min_cost:
                min_cost = c

    # Check pairs
    for i in range(N):
        for j in range(N):
            s1, c1 = strings[i]
            s2, c2 = strings[j]
            for order in [(s1, s2), (s2, s1)]:
                combined = ''.join(order)
                if is_palindrome(combined):
                    total_cost = c1 + c2
                    if total_cost < min_cost:
                        min_cost = total_cost

    # Check triplets
    for i in range(N):
        for j in range(N):
            for k in range(N):
                s1, c1 = strings[i]
                s2, c2 = strings[j]
                s3, c3 = strings[k]
                for perm in permutations([s1, s2, s3]):
                    combined = ''.join(perm)
                    if is_palindrome(combined):
                        total_cost = c1 + c2 + c3
                        if total_cost < min_cost:
                            min_cost = total_cost

    if min_cost == float('inf'):
        print(-1)
    else:
        print(min_cost)

