def main():
    import sys
    input = sys.stdin.read
    n, k = map(int, input().split())

    from collections import defaultdict

    dp = defaultdict(lambda: defaultdict(int))
    dp[0][0] = 1

    for mask in range(0, 1 << n):
        if not dp[mask]:
            continue
        m = bin(mask).count('1')
        for x in range(n):
            if not (mask & (1 << x)):
                new_mask = mask | (1 << x)
                contribution = abs((m + 1) - (x + 1))
                for s in list(dp[mask].keys()):
                    new_s = s + contribution
                    if new_s > k:
                        continue
                    dp[new_mask][new_s] = (dp[new_mask][new_s] + dp[mask][s]) % MOD

    print(dp[(1 << n) - 1][k] % MOD)

