    if k % 2 != 0:
        print(0)
        return

    max_sum = n * n
    dp = [[0] * (max_sum + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for s in range(max_sum + 1):
            for x in range(1, n + 1):
                contribution = abs(i - x)
                if s >= contribution:
                    dp[i][s] = (dp[i][s] + dp[i-1][s - contribution]) % MOD

    print(dp[n][k] % MOD)

