import sys

def factorize(n):
    factors = {}
    i = 2
    while i * i <= n:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n = n // i
        i += 1
    if n > 1:
        factors[n] = 1
    return factors

def get_divisors(factors):
    divisors = [1]
    for p, exp in factors.items():
        temp = []
        p_pows = [p**e for e in range(exp + 1)]
        for d in divisors:
            for pow_val in p_pows:
                temp.append(d * pow_val)
        divisors = temp
    return divisors

def main():
    N = int(sys.stdin.readline())
    # Compute count1: number of divisors of N-1 >=2
    N_minus_1 = N - 1
    if N_minus_1 == 0:
        count1 = 0
    else:
        factors = factorize(N_minus_1)
        divisors = get_divisors(factors)
        count1 = len([d for d in divisors if d >= 2])
    # Compute count2: number of divisors of N (excluding 1) that satisfy the condition
    factors_N = factorize(N)
    divisors_N = get_divisors(factors_N)
    count2 = 0
    for K in divisors_N:
        if K == 1:
            continue
        temp = N
        while temp % K == 0:
            temp = temp // K
        if temp % K == 1:
            count2 += 1
    print(count1 + count2)

