import math

def main():
    sys.setrecursionlimit(1000000)
    N = int(sys.stdin.readline())
    memo = {}

    def get_divisors(x):
        divisors = set()
        for i in range(1, int(math.isqrt(x)) + 1):
            if x % i == 0:
                divisors.add(i)
                divisors.add(x // i)
        return divisors

    def f(m):
        if m in memo:
            return memo[m]
        if m == 1:
            return 0
        # Part 1: Count divisors of m-1 >= 2
        x = m - 1
        if x == 0:
            part1 = 0
        else:
            divisors_x = get_divisors(x)
            part1 = len(divisors_x) - 1
        # Part 2: Count valid divisors of m
        part2 = 0
        divisors_m = get_divisors(m)
        for d in divisors_m:
            if d >= 2:
                q = m // d
                if q == 1:
                    part2 += 1
                else:
                    if f(q) == 1:
                        part2 += 1
        memo[m] = part1 + part2
        return memo[m]

    result = f(N)
    print(result)

