def main():
    N, K = map(int, sys.stdin.readline().split())
    matrix = [list(map(int, sys.stdin.readline().split())) for _ in range(N)]

    # Build row graph
    row_graph = [[] for _ in range(N)]
    for i in range(N):
        for j in range(i+1, N):
            valid = True
            for col in range(N):
                if matrix[i][col] + matrix[j][col] > K:
                    valid = False
                    break
            if valid:
                row_graph[i].append(j)
                row_graph[j].append(i)

    # Build column graph
    col_graph = [[] for _ in range(N)]
    for x in range(N):
        for y in range(x+1, N):
            valid = True
            for row in range(N):
                if matrix[row][x] + matrix[row][y] > K:
                    valid = False
                    break
            if valid:
                col_graph[x].append(y)
                col_graph[y].append(x)

    # Find connected components for rows
    visited_rows = [False] * N
    row_components = []
    for i in range(N):
        if not visited_rows[i]:
            q = deque()
            q.append(i)
            visited_rows[i] = True
            component_size = 0
            while q:
                node = q.popleft()
                component_size += 1
                for neighbor in row_graph[node]:
                    if not visited_rows[neighbor]:
                        visited_rows[neighbor] = True
                        q.append(neighbor)
            row_components.append(component_size)

    # Find connected components for columns
    visited_cols = [False] * N
