                node = q.popleft()
                component_size += 1
                for neighbor in col_graph[node]:
                    if not visited_cols[neighbor]:
                        visited_cols[neighbor] = True
                        q.append(neighbor)
            col_components.append(component_size)

    # Compute factorial product for row components
    row_result = 1
    for size in row_components:
        fact = 1
        for i in range(1, size+1):
