    target = rest_xor
    K = A[0] + A[1]

    if (K - target) < 0 or (K - target) % 2 != 0:
        print(-1)
        return

    c = (K - target) // 2
    if (target & c) != 0:
        print(-1)
        return

    C = c + target - A[1]

    x = 0
    for bit in reversed(range(61)):
        if (target >> bit) & 1:
            temp = x | (1 << bit)
            if temp <= C:
                x = temp

    x_stones = C - x
    if 0 <= x_stones <= A[0] - 1:
        print(x_stones)
    else:
        print(-1)

