    def count_subsets(C, K):
        from functools import lru_cache

        max_bit = K.bit_length()
        @lru_cache(maxsize=None)
        def dfs(pos, tight):
            if pos == -1:
                return 1
            res = 0
            current_bit = (K >> pos) & 1
            c_bit = (C >> pos) & 1
            if c_bit == 0:
                new_tight = tight and (current_bit == 0)
                res += dfs(pos - 1, new_tight)
            else:
                res += dfs(pos - 1, tight)
                if tight:
                    if current_bit == 1:
                        res += dfs(pos - 1, False)
                else:
                    res += dfs(pos - 1, False)
            return res
        return dfs(max_bit - 1, True)

    for x in range(L, R + 1):
        K = min(x - 1, R - x)
        if K < 0:
            continue
        b = x.bit_length()
        C = ((1 << b) - 1) ^ x
        m = b - bin(x).count('1')
        M = (1 << m) - 1
        if M <= K:
            ans += (1 << m)
        else:
            cnt = count_subsets(C, K)
            ans += cnt
        ans %= MOD

