def get_binary(n):
    if n == 0:
        return [0]
    bits = []
    while n > 0:
        bits.append(n & 1)
        n >>= 1
    bits.reverse()
    return bits

def compute_sum(n):
    if n == 0:
        return 2 % MOD
    bits = get_binary(n)
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, tight, started, zeros):
        if pos == len(bits):
            if started:
                return pow(2, zeros, MOD)
            else:
                return pow(2, 1, MOD)
        limit = bits[pos] if tight else 1
        total = 0
        for bit in range(0, limit + 1):
            new_tight = tight and (bit == limit)
            new_started = started or (bit == 1)
            new_zeros = zeros
            if not new_started:
                if bit == 0:
                    pass
                else:
                    new_zeros = 0
            else:
                if bit == 0:
                    new_zeros += 1
            total += dp(pos + 1, new_tight, new_started, new_zeros)
            total %= MOD
        return total

    result = dp(0, True, False, 0)
    return result

