def compute_S(M):
    if M == 0:
        return 1
    bits = []
    m = M
    while m > 0:
        bits.append(m % 2)
        m = m // 2
    bits = bits[::-1]  # MSB first
    inv2 = pow(2, MOD-2, MOD)
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, tight, count):
        if pos == len(bits):
            return pow(inv2, count, MOD)
        limit = bits[pos] if tight else 1
        res = 0
        for d in range(0, limit + 1):
            new_tight = tight and (d == limit)
            new_count = count + (d == 1)
            res = (res + dp(pos + 1, new_tight, new_count)) % MOD
        return res

    return dp(0, True, 0)

def total(N):
    if N == 0:
        return 0
    res = 0
    k = 0
    while True:
        low = 1 << k
        if low > N:
            break
        high = (1 << (k + 1)) - 1
        if high <= N:
            contribution = pow(3, k, MOD)
        else:
            M = N - low
            s = compute_S(M)
            contribution = (pow(2, k, MOD) * s) % MOD
        res = (res + contribution) % MOD
        k += 1
    return res

