    L, R = map(int, sys.stdin.readline().split())

    def compute_partial_sum(M, b, inv_2):
        binary_str = bin(M)[2:]
        assert len(binary_str) == b
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(pos, count_set, tight):
            if pos == b:
                return pow(inv_2, count_set, MOD)
            limit = int(binary_str[pos]) if tight else 1
            total = 0
            for bit in [0, 1]:
                if bit > limit:
                    continue
                new_tight = tight and (bit == limit)
                new_count = count_set + (bit == 1)
                total += dp(pos + 1, new_count, new_tight)
                total %= MOD
            return total

        result = dp(1, 1, True)
        return result

    def sum_upto(N):
        if N == 0:
            return 0
        total = 0
        b = 1
        while True:
            low = 1 << (b-1)
            high = (1 << b) - 1
            if low > N:
                break
            if high <= N:
                total += pow(3, b-1, MOD)
                total %= MOD
            else:
                partial = compute_partial_sum(N, b, inv_2)
                partial_contribution = (partial * pow(2, b, MOD)) % MOD
                total += partial_contribution
                total %= MOD
            b += 1
        return total

    inv_2 = pow(2, MOD-2, MOD)
    ans = (sum_upto(R) - sum_upto(L-1)) % MOD
    print(ans)

