        n = len(packages)
        subsets = []
        for mask in range(1 << n):
            sumA = 0
            sumB = 0
            cost = 0
            is_empty = True
            for i in range(n):
                if mask & (1 << i):
                    sumA += packages[i][0]
                    sumB += packages[i][1]
                    cost += packages[i][2]
                    is_empty = False
            subsets.append( (sumA, sumB, cost, is_empty) )
