def main():
    H, W = map(int, sys.stdin.readline().split())
    grid = [sys.stdin.readline().strip() for _ in range(H)]
    road_squares = [(i, j) for i in range(H) for j in range(W) if grid[i][j] == '.']
    max_dist = 0
    for (start_i, start_j) in road_squares:
        dist = [[-1] * W for _ in range(H)]
        q = deque()
        dist[start_i][start_j] = 0
        q.append((start_i, start_j))
        while q:
            i, j = q.popleft()
            for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < H and 0 <= nj < W:
                    if grid[ni][nj] == '.' and dist[ni][nj] == -1:
                        dist[ni][nj] = dist[i][j] + 1
                        q.append((ni, nj))
        current_max = max(dist[i][j] for i in range(H) for j in range(W))
        if current_max > max_dist:
            max_dist = current_max
    print(max_dist)

