def main():
    import sys
    N, X = map(int, sys.stdin.read().split())
    total_layers = [0] * (N + 1)
    total_patties = [0] * (N + 1)
    total_layers[0] = 1
    total_patties[0] = 1
    for l in range(1, N + 1):
        total_layers[l] = 3 + 2 * total_layers[l - 1]
        total_patties[l] = 2 * total_patties[l - 1] + 1

    def count_patties(L, X):
        if L == 0:
            return 1 if X >= 1 else 0
        T = total_layers[L - 1]
        if X == 1:
            return 0
        elif X <= T + 1:
            return count_patties(L - 1, X - 1)
        elif X == T + 2:
            return count_patties(L - 1, T) + 1
        elif X <= T + 2 + T:
            return count_patties(L - 1, T) + 1 + count_patties(L - 1, X - (T + 2))
        else:
            return count_patties(L - 1, T) + 1 + count_patties(L - 1, T)

    print(count_patties(N, X))

