def main():
    import sys
    from collections import defaultdict

    N = int(sys.stdin.readline())
    dp = [defaultdict(int) for _ in range(N+1)]
    dp[0][""] = 1

    for i in range(1, N+1):
        for state in dp[i-1]:
            count = dp[i-1][state]
            for c in ['A', 'C', 'G', 'T']:
                if i-1 < 3:
                    new_state = state + c
                else:
                    new_state = state[1:] + c
                if i >= 3:
                    if new_state == 'AGC':
                        continue
                    if i-1 >= 3:
                        if state == 'GAC':
                            continue
                    if new_state in {'GAC', 'ACG'}:
                        continue
                dp[i][new_state] = (dp[i][new_state] + count) % MOD

    print(sum(dp[N].values()) % MOD)

