def is_invalid_4_char(seq):
    # seq is a tuple of 4 characters
    # check all three possible swaps
    # swap 0 and 1
    swapped = list(seq)
    swapped[0], swapped[1] = swapped[1], swapped[0]
    if ''.join(swapped[:3]) == 'AGC' or ''.join(swapped[1:4]) == 'AGC':
        return True
    # swap 1 and 2
    swapped = list(seq)
    swapped[1], swapped[2] = swapped[2], swapped[1]
    if ''.join(swapped[:3]) == 'AGC' or ''.join(swapped[1:4]) == 'AGC':
        return True
    # swap 2 and 3
    swapped = list(seq)
    swapped[2], swapped[3] = swapped[3], swapped[2]
    if ''.join(swapped[:3]) == 'AGC' or ''.join(swapped[1:4]) == 'AGC':
        return True
    return False

