    @lru_cache(maxsize=None)
    def dfs(i, turn, x, y):
        if i >= N:
            return abs(x - y)
        if turn == 0:  # X's turn
            max_val = -1
            for m in range(1, N - i + 1):
                new_x = a[i + m - 1]
                res = dfs(i + m, 1, new_x, y)
                if res > max_val:
                    max_val = res
            return max_val
        else:  # Y's turn
            min_val = float('inf')
            for m in range(1, N - i + 1):
                new_y = a[i + m - 1]
                res = dfs(i + m, 0, x, new_y)
                if res < min_val:
                    min_val = res
            return min_val

    result = dfs(0, 0, Z, W)
    print(result)

