        items.append((w, v))

    w1 = items[0][0]
    group0 = []
    group1 = []
    group2 = []
    group3 = []

    for w, v in items:
        diff = w - w1
        if diff == 0:
            group0.append(v)
        elif diff == 1:
            group1.append(v)
        elif diff == 2:
            group2.append(v)
        elif diff == 3:
            group3.append(v)

    group0.sort(reverse=True)
    group1.sort(reverse=True)
    group2.sort(reverse=True)
    group3.sort(reverse=True)

    # Compute prefix sums
    prefix_sum_0 = [0]
    for v in group0:
        prefix_sum_0.append(prefix_sum_0[-1] + v)

    prefix_sum_1 = [0]
    for v in group1:
        prefix_sum_1.append(prefix_sum_1[-1] + v)

    prefix_sum_2 = [0]
    for v in group2:
        prefix_sum_2.append(prefix_sum_2[-1] + v)

    prefix_sum_3 = [0]
    for v in group3:
        prefix_sum_3.append(prefix_sum_3[-1] + v)

    max_total = 0

    for k in range(0, N + 1):
        T = W - k * w1
        if T < 0:
            continue
        effective_capacity = min(T, 3 * k)
        if effective_capacity < 0:
            continue
        # Initialize dp
        dp = [[-float('inf')] * (k + 1) for _ in range(effective_capacity + 1)]
        dp[0][0] = 0

        # Process group1
        for item in group1:
            item_weight = 1
            item_value = item
            for t in range(effective_capacity, item_weight - 1, -1):
                for m in range(k, 0, -1):
                    if dp[t - item_weight][m - 1] + item_value > dp[t][m]:
                        dp[t][m] = dp[t - item_weight][m - 1] + item_value

        # Process group2
        for item in group2:
            item_weight = 2
            item_value = item
            for t in range(effective_capacity, item_weight - 1, -1):
                for m in range(k, 0, -1):
                    if dp[t - item_weight][m - 1] + item_value > dp[t][m]:
                        dp[t][m] = dp[t - item_weight][m - 1] + item_value

        # Process group3
        for item in group3:
            item_weight = 3
            item_value = item
            for t in range(effective_capacity, item_weight - 1, -1):
                for m in range(k, 0, -1):
                    if dp[t - item_weight][m - 1] + item_value > dp[t][m]:
                        dp[t][m] = dp[t - item_weight][m - 1] + item_value

        # Now, find the maximum value for this k
        current_max = 0
        for m in range(0, k + 1):
            max_val = -float('inf')
            for t in range(effective_capacity + 1):
                if dp[t][m] > max_val:
                    max_val = dp[t][m]
            if max_val != -float('inf'):
                a = k - m
