    input = sys.stdin.read().split()
    N = int(input[0])
    strings = input[1:N+1]

    total_balance = 0
    positive = []
    negative = []
    zero = []

    for s in strings:
        balance = 0
        min_b = 0
        max_b = 0
        for c in s:
            if c == '(':
                balance += 1
            else:
                balance -= 1
            min_b = min(min_b, balance)
            max_b = max(max_b, balance)
        total_balance += balance
        if balance > 0:
            positive.append((min_b, balance))
        elif balance < 0:
            negative.append((max_b, min_b, balance))
        else:
            zero.append((min_b, balance))

    if total_balance != 0:
        print("No")
        return

    positive.sort(key=lambda x: -x[0])
    zero.sort(key=lambda x: -x[0])
    negative.sort(key=lambda x: -x[0])

    current_balance = 0

    for min_b, bal in positive:
        if current_balance + min_b < 0:
            print("No")
            return
        current_balance += bal

    for min_b, bal in zero:
        if current_balance + min_b < 0:
            print("No")
            return
        current_balance += bal

    for max_b, min_b, bal in negative:
        if current_balance + min_b < 0:
            print("No")
            return
        current_balance += bal

    print("Yes")

