def main():
    import sys
    input = sys.stdin.read().split()
    N = int(input[0])
    s = list(map(int, input[1:N+1]))

    max_score = 0

    # Handle k=0 case: A = N-1, score is s[N-1]
    max_score = max(max_score, s[N-1])

    # Handle k=1 case
    for A in range(1, N):
        if A > (N-1)/2 and A != N-1:
            B = 2 * A - (N-1)
            if B > 0:
                # Check if positions are distinct
                pos1 = A
                pos2 = N-1 - A
                positions = {0, pos1, pos2, N-1}
                if len(positions) == 4:
                    score = s[pos1] + s[pos2] + s[N-1]
                    max_score = max(max_score, score)

    print(max_score)

