import sys

def main():
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    s = list(map(int, data[1:N+1]))
    max_score = 0

    # Case k=1 (m=3)
    for A in range((N-1)//2 + 1, N):
        B = 2 * A - (N-1)
        if B > 0:
            x1 = A
            x2 = N-1 - A
            if x1 != x2 and x1 != 0 and x2 != 0 and x1 != N-1 and x2 != N-1:
                score = s[x1] + s[x2]
                if score > max_score:
                    max_score = score

    # Case k=2 (m=5)
    for A in range((N-1)//3 + 1, N):
        numerator = 3 * A - (N-1)
        if numerator > 0 and numerator % 2 == 0:
            B = numerator // 2
            positions = [0, A, A - B, 2*A - B, 2*A - 2*B, N-1]
            valid = True
            for pos in positions:
                if pos < 0 or pos >= N:
                    valid = False
                    break
            if valid:
                seen = set()
                for pos in positions:
                    if pos in seen:
                        valid = False
                        break
                    seen.add(pos)
                if valid:
                    score = s[A] + s[A - B] + s[2*A - B] + s[2*A - 2*B]
                    if score > max_score:
                        max_score = score

    print(max_score)

