        current = 0
        positions = {0}
        valid = True
        for step in range(1, 2 * m + 2):
            if step % 2 == 1:
                current += A
            else:
                current -= B
            if current < 0 or current >= N:
                valid = False
                break
            if current in positions:
                valid = False
                break
            positions.add(current)

        if valid:
            # Re-run to collect positions list
            current = 0
            positions_list = [0]
            for step in range(1, 2 * m + 2):
                if step % 2 == 1:
                    current += A
                else:
                    current -= B
                if current < 0 or current >= N:
