    N = int(data[0])
    s = list(map(int, data[1:N+1]))
    max_score = -10**18

    # Handle m=0 case: A = N-1, B can be any positive integer, score is s[N-1] = 0
    max_score = max(max_score, 0)

    for m in range(1, N):
        r = (N-1) % m
        A_min = (N-1) // (m + 1) + 1
        A_max = N - 1

        # Calculate k_min and k_max
        numerator = A_min - r
        if numerator <= 0:
            k_min = 0
        else:
            k_min = (numerator + m - 1) // m  # ceil division
        k_max = (A_max - r) // m

        for k in range(k_min, k_max + 1):
            A = r + k * m
            if A < A_min or A > A_max:
                continue
            numerator_B = (m + 1) * A - (N - 1)
            if numerator_B <= 0:
                continue
            if numerator_B % m != 0:
                continue
            B = numerator_B // m

            # Check if all positions are valid and unique
            positions = set()
            valid = True
            for i in range(1, 2 * m + 2):
                if i % 2 == 1:
                    k_steps = (i + 1) // 2
                    l_steps = (i - 1) // 2
                else:
                    k_steps = i // 2
                    l_steps = k_steps
                pos = k_steps * A - l_steps * B
                if pos < 0 or pos >= N:
                    valid = False
                    break
                if pos in positions:
                    valid = False
                    break
                positions.add(pos)
            if valid:
                # Calculate score
                score = 0
                for i in range(1, 2 * m + 2):
                    if i % 2 == 1:
                        k_steps = (i + 1) // 2
                        l_steps = (i - 1) // 2
                    else:
                        k_steps = i // 2
                        l_steps = k_steps
                    pos = k_steps * A - l_steps * B
                    if 0 <= pos < N:
                        score += s[pos]
                if score > max_score:
                    max_score = score

    print(max_score)

