import math
from math import gcd
from functools import reduce

def main():
    input = sys.stdin.read().split()
    N = int(input[0])
    A = list(map(int, input[1:N+1]))

    # Compute overall GCD
    overall_gcd = A[0]
    for num in A[1:]:
        overall_gcd = math.gcd(overall_gcd, num)

    if overall_gcd != 1:
        print("not coprime")
        return

    # Precompute smallest prime factors (SPF)
    max_num = 10**6
    spf = list(range(max_num + 1))
    for i in range(2, int(max_num**0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, max_num + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # Check pairwise coprime
    freq = {}
    for num in A:
        if num == 1:
            continue
        x = num
        primes = set()
        while x != 1:
            p = spf[x]
            primes.add(p)
            while x % p == 0:
                x //= p
        for p in primes:
            if p in freq:
                freq[p] += 1
            else:
                freq[p] = 1

    pairwise = True
    for count in freq.values():
        if count >= 2:
            pairwise = False
            break

    if pairwise:
        print("pairwise coprime")
    else:
        print("setwise coprime")

