    def __init__(self):
        self.basis = [0] * 60

    def insert(self, x):
        for i in reversed(range(60)):
            if (x >> i) & 1:
                if self.basis[i] == 0:
                    self.basis[i] = x
                    return True
                else:
                    x ^= self.basis[i]
        return False

