def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    R = int(input[idx]); idx +=1
    C = int(input[idx]); idx +=1
    K = int(input[idx]); idx +=1

    rows = [[] for _ in range(R+1)]
    for _ in range(K):
        r = int(input[idx]); idx +=1
        c = int(input[idx]); idx +=1
        v = int(input[idx]); idx +=1
        rows[r].append((c, v))

    # Preprocess each row
    row_sorted_cols = [[] for _ in range(R+1)]
    row_prefix_sums = [[] for _ in range(R+1)]

    for i in range(1, R+1):
        items = rows[i]
        sorted_items = sorted(items, key=lambda x: x[0])
        sorted_cols = [c for c, v in sorted_items]
        sorted_vals = [v for c, v in sorted_items]
        n = len(sorted_vals)
        # Compute prefix_sums for this row
        prefix_sums = [[0, 0, 0, 0]]  # x=0
        top3 = []
        for x in range(1, n+1):
            val = sorted_vals[x-1]
            top3.append(val)
            top3.sort(reverse=True)
            if len(top3) > 3:
                top3.pop()
            # compute sum_0, sum_1, sum_2, sum_3
            sum_0 = 0
            sum_1 = top3[0] if len(top3) >=1 else 0
            sum_2 = sum_1 + (top3[1] if len(top3) >=2 else 0)
            sum_3 = sum_2 + (top3[2] if len(top3) >=3 else 0)
            prefix_sums.append([sum_0, sum_1, sum_2, sum_3])
        row_sorted_cols[i] = sorted_cols
        row_prefix_sums[i] = prefix_sums

    # Initialize DP
    INF = float('-inf')
    # dp[i][j][m] = max sum up to (i,j) with m items collected in row i
    dp = [[[INF]*4 for _ in range(C+1)] for _ in range(R+1)]

    # Initialize first cell (1,1)
    i = 1
    j = 1
    sorted_cols = row_sorted_cols[i]
    x = bisect.bisect_right(sorted_cols, j)
    prefix = row_prefix_sums[i][x]
    for m in range(4):
        dp[i][j][m] = prefix[m]

    # Process other cells
    for i in range(1, R+1):
        for j in range(1, C+1):
            if i == 1 and j == 1:
                continue
            # compute x for current row i and column j
            sorted_cols = row_sorted_cols[i]
            x = bisect.bisect_right(sorted_cols, j)
            prefix = row_prefix_sums[i][x]
            # compute max_prev_above and max_prev_left
            max_prev_above = INF
            if i > 1:
                max_prev_above = max(dp[i-1][j][0], dp[i-1][j][1], dp[i-1][j][2], dp[i-1][j][3])
            max_prev_left = INF
            if j > 1:
                max_prev_left = max(dp[i][j-1][0], dp[i][j-1][1], dp[i][j-1][2], dp[i][j-1][3])
            current_max = max(max_prev_above, max_prev_left)
            for m in range(4):
                dp[i][j][m] = current_max + prefix[m]

    # The answer is the maximum of dp[R][C][0], dp[R][C][1], dp[R][C][2], dp[R][C][3]
    ans = max(dp[R][C][0], dp[R][C][1], dp[R][C][2], dp[R][C][3])
    print(ans)

