import sys
import math
from collections import defaultdict

MOD = 10**9 + 7

def normalize(a, b):
    if a == 0 and b == 0:
        return (0, 0)
    g = math.gcd(abs(a), abs(b))
    a //= g
    b //= g
    if a == 0:
        if b < 0:
            b = -b
    else:
        if a < 0:
            a = -a
            b = -b
    return (a, b)

def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    dir_count = defaultdict(int)
    count_0 = 0
    for _ in range(N):
        a = int(input[idx])
        b = int(input[idx+1])
        idx += 2
        if a == 0 and b == 0:
            count_0 += 1
        else:
            d = normalize(a, b)
            dir_count[d] += 1
    processed = set()
    product = 1
    for d in dir_count:
        if d not in processed:
            x, y = d
            perp_x = -y
            perp_y = x
            perp_dir = normalize(perp_x, perp_y)
            if perp_dir not in dir_count:
                contribution = pow(2, dir_count[d], MOD)
                product = (product * contribution) % MOD
                processed.add(d)
            else:
                if perp_dir not in processed:
                    m_d = dir_count[d]
                    m_dp = dir_count[perp_dir]
                    contribution = (pow(2, m_d, MOD) + pow(2, m_dp, MOD) - 1) % MOD
                    product = (product * contribution) % MOD
                    processed.add(d)
                    processed.add(perp_dir)
    total_non_zero = (product - 1) % MOD
    if count_0 >= 1:
        ans = (total_non_zero + count_0) % MOD
    else:
        ans = total_non_zero
    print(ans)

if __name__ == '__main__':
    main()
