import sys
from collections import defaultdict

s = sys.stdin.readline().strip()
n = len(s)

if n < 2:
    print(-1, -1)
    sys.exit()

# Check for consecutive duplicates
for i in range(n - 1):
    if s[i] == s[i + 1]:
        print(i + 1, i + 2)
        sys.exit()

# Check for three consecutive characters with first and third same
for i in range(n - 2):
    if s[i] == s[i + 2]:
        print(i + 1, i + 3)
        sys.exit()

# Check for any character with two occurrences separated by exactly one character
positions = defaultdict(list)
for idx, c in enumerate(s):
    positions[c].append(idx)

for c in positions:
    lst = positions[c]
    for i in range(len(lst) - 1):
        if lst[i + 1] - lst[i] == 2:
            print(lst[i] + 1, lst[i + 1] + 1)
            sys.exit()

